/*
 * Check bc_webgl2_ref_conv_first_slice against mn_conv_first.
 *
 * WHY. backend_webgl2.c's layer-0 verification compares the GPU against
 * bc_webgl2_ref_conv_first_slice, not against the project's actual reference.
 * That would be circular -- my code agreeing with my code -- unless the
 * reference is itself pinned to meshnet_cpu.c. It cannot be pinned inside the
 * wasm module: mn_conv_first is static, generated by MN_DEFINE_CONV, which
 * project policy forbids restructuring, and its output is 1.07 GiB. Natively, both
 * problems disappear -- including meshnet_cpu.c makes the static function
 * visible, and 1.07 GiB is an ordinary allocation.
 *
 * Including a .c file is deliberate and confined to this test. It means the
 * shipped meshnet_cpu.o is untouched, so nothing here can perturb the codegen
 * benchmarking measures.
 *
 * NOT bit-exactness. Both functions live in this translation unit under the
 * same flags, but MN_DEFINE_CONV is register-blocked and vectorised while the
 * reference is a plain scalar loop, so the compiler contracts them differently
 * and the last bits diverge. That is not what is being tested. A structural
 * error -- a transposed tap, wrong padding, a mis-indexed kernel -- moves
 * results by order 1, not by 1e-7, so a tight relative bound separates the two
 * cleanly.
 */

#include "../src/meshnet_cpu.c"
#include "../src/webgl2_ref_conv.h"

#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define DIM BRAINCHOP_MODEL_DIM
#define NVOX ((size_t)DIM * DIM * DIM)
#define CS MESHNET_CPU_CHANNEL_STRIDE

/* A deterministic generator, so a failure is reproducible without a seed file. */
static uint32_t rng_state = 0x2545f491u;
static float next_float(void) {
	rng_state ^= rng_state << 13;
	rng_state ^= rng_state >> 17;
	rng_state ^= rng_state << 5;
	return (float)(rng_state >> 8) * (1.0f / 16777216.0f) - 0.5f;
}

int main(void) {
	float *input = (float *)malloc(NVOX * sizeof(*input));
	float *dest = (float *)malloc(NVOX * CS * sizeof(*dest));
	float *kernel = (float *)malloc((size_t)27 * CS * sizeof(*kernel));
	float *slice = (float *)malloc((size_t)DIM * DIM * CS * sizeof(*slice));
	if (!input || !dest || !kernel || !slice) {
		fprintf(stderr, "out of memory (needs about %.1f GB)\n",
			(double)(NVOX * CS * sizeof(float)) / 1e9);
		return 1;
	}
	for (size_t i = 0; i < NVOX; i++) input[i] = next_float();
	/* The pad lanes beyond BC_MODEL_CHAN are zero, exactly as
	   meshnet_cpu_pack_kernel calloc()s them; a nonzero pad would make the two
	   implementations disagree for a reason that cannot occur in practice. */
	for (size_t t = 0; t < 27; t++)
		for (int c = 0; c < CS; c++)
			kernel[t * CS + c] = c < BC_MODEL_CHAN ? next_float() : 0.0f;

	mn_region region = { 0, DIM - 1, 0, DIM - 1, 0, DIM - 1, NVOX };

	int failures = 0;
	/* Every dilation the shipped models use for layer 0, plus 1 and a large
	   one, so the padding path is exercised at both extremes. */
	const int dilations[] = { 1, 2, 4, 8, 16, 31 };
	for (size_t d = 0; d < sizeof(dilations) / sizeof(*dilations); d++) {
		int dilation = dilations[d];
		mn_conv_first(input, dest, kernel, dilation, &region);

		/* z = 0 exercises the low-z zero padding; DIM/2 is fully interior;
		   DIM-1 exercises the high-z face. */
		const int slices[] = { 0, DIM / 2, DIM - 1 };
		for (size_t s = 0; s < sizeof(slices) / sizeof(*slices); s++) {
			int z = slices[s];
			bc_webgl2_ref_conv_first_slice(input, kernel, dilation, z, DIM, CS, slice);
			double worst = 0.0, peak = 0.0;
			size_t exact = 0, total = (size_t)DIM * DIM * CS;
			for (size_t i = 0; i < total; i++) {
				double a = dest[(size_t)z * DIM * DIM * CS + i], b = slice[i];
				if (a == b) exact++;
				double diff = fabs(a - b);
				if (diff > worst) worst = diff;
				if (fabs(a) > peak) peak = fabs(a);
			}
			/*
			 * A slice whose reference is identically zero would score rel = 0
			 * and pass while comparing nothing -- the same VACUOUS trap the
			 * browser comparison in backend_webgl2.c names and guards. It is
			 * unreachable with the random input above, which is exactly why it
			 * has to be asserted rather than assumed: this check is what pins
			 * the reference to mn_conv_first, so if it ever silently stops
			 * comparing, the browser gate above it means nothing either.
			 */
			int vacuous = !(peak > 0.0);
			double relative = vacuous ? 1.0 : worst / peak;
			int bad = vacuous || !(relative < 1e-5);
			if (bad) failures++;
			printf("%s dilation %2d z=%3d: exact %.4f%%  max|d|=%.3e  "
				"peak=%.3e  rel=%.3e%s\n", bad ? "FAIL" : "ok  ", dilation, z,
				100.0 * (double)exact / (double)total, worst, peak, relative,
				vacuous ? "  VACUOUS - the reference is identically zero" : "");
		}
	}

	free(input); free(dest); free(kernel); free(slice);
	if (failures) {
		printf("FAILED: the webgl2 reference disagrees with mn_conv_first\n");
		return 1;
	}
	printf("ok: the webgl2 reference matches mn_conv_first on every case\n");
	return 0;
}
